alert.Dismissible:
import * as React from 'react';
import { Alert, Button } from '@bindshq/stance-react';

export function Dismissible() {
  const [open, setOpen] = React.useState(true);
  return open ? (
    <Alert tone="success" title="Import complete" onDismiss={() => setOpen(false)}>
      120 users were added to your organisation.
    </Alert>
  ) : (
    <Button variant="outline" size="sm" onClick={() => setOpen(true)}>
      Show again
    </Button>
  );
}

aspect-ratio.Basic:
import { AspectRatio } from '@bindshq/stance-react';

const art = (label: string) => (
  <svg viewBox="0 0 160 90" preserveAspectRatio="xMidYMid slice" role="img" aria-label={label}>
