    <circle cx="120" cy="30" r="40" fill="var(--st-color-bg-emphasis)" />
    <rect x="16" y="56" width="64" height="8" rx="4" fill="var(--st-color-fg-subtle)" />
    <rect x="16" y="70" width="40" height="6" rx="3" fill="var(--st-color-border-strong)" />
