import { CommandEmpty, CommandInput, CommandItem, CommandList, CommandMenu, Icon } from '@bindshq/stance-react';

const box: React.CSSProperties = { width: 'min(440px, 100%)' };

const people = [
  'Ada Lovelace',
  'Grace Hopper',
  'Katherine Johnson',
  'Alan Turing',
  'Margaret Hamilton',
];

export function ServerFiltering() {
  const [search, setSearch] = React.useState('');
  // Stand-in for a server query: case-insensitive "contains".
  const results = people.filter((p) => p.toLowerCase().includes(search.toLowerCase()));
  return (
    <CommandMenu
      label="Find a person"
      search={search}
      onSearchChange={setSearch}
      filter={false}
      style={box}
    >
      <CommandInput placeholder="Search people…" />
      <CommandList>
        {results.map((p) => (
          <CommandItem key={p} value={p} icon={<Icon name="user" />} />
        ))}
      </CommandList>
      <CommandEmpty>No people found.</CommandEmpty>
    </CommandMenu>
  );
}

