confirmation-dialog.Async:
import * as React from 'react';
import { Button, ConfirmationDialog } from '@bindshq/stance-react';

export function Async() {
  const attempts = React.useRef(0);
  return (
    <ConfirmationDialog
      trigger={<Button>Deploy signatures</Button>}
      title="Deploy to 128 mailboxes?"
      description="Signatures are pushed through your Exchange relay."
      confirmLabel="Deploy"
      loadingText="Deploying…"
      onConfirm={() =>
        new Promise<void>((resolve, reject) => {
          attempts.current += 1;
          setTimeout(() => {
            if (attempts.current % 2 === 1)
              reject(new Error('Exchange did not respond. Try again.'));
            else resolve();
          }, 1200);
        })
      }
    />
  );
}

confirmation-dialog.Imperative:
import * as React from 'react';
import { Button, ConfirmProvider, useConfirm } from '@bindshq/stance-react';

function DeleteButton() {
  const confirm = useConfirm();
  const [status, setStatus] = React.useState('');
  return (
    <div style={{ display: 'grid', gap: 8, justifyItems: 'center' }}>
      <Button
        variant="outline"
        onClick={async () => {
          const ok = await confirm({
            title: 'Archive “Q3 campaign”?',
            description: 'Archived templates can be restored for 30 days.',
            confirmLabel: 'Archive',
          });
          setStatus(ok ? 'Archived.' : 'Kept.');
        }}
      >
        Archive template
      </Button>
      <span aria-live="polite">{status}</span>
    </div>
  );
}

export function Imperative() {
  return (
    <ConfirmProvider>
      <DeleteButton />
    </ConfirmProvider>
  );
}

