table.Sortable:
import * as React from 'react';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@bindshq/stance-react';
import type { SortDirection } from '@bindshq/stance-react';

const users = [
  {
    name: 'Amara Okafor',
    email: 'amara@binds.si',
    department: 'Sales',
    status: 'Deployed',
    signatures: 3,
  },
  {
    name: 'Lukas Novak',
    email: 'lukas@binds.si',
    department: 'Engineering',
    status: 'Pending',
    signatures: 1,
  },
  {
    name: 'Priya Raman',
    email: 'priya@binds.si',
    department: 'Legal',
    status: 'Deployed',
    signatures: 2,
  },
  {
    name: 'Tomás Ferreira',
    email: 'tomas@binds.si',
    department: 'Support',
    status: 'Failed',
    signatures: 0,
  },
  {
    name: 'Hana Sato',
    email: 'hana@binds.si',
    department: 'Marketing',
    status: 'Deployed',
    signatures: 4,
  },
  {
    name: 'Oliver Grant',
    email: 'oliver@binds.si',
    department: 'Finance',
    status: 'Pending',
    signatures: 1,
  },
];

export function Sortable() {
  const [sort, setSort] = React.useState<{ key: 'name' | 'signatures'; dir: SortDirection }>({
    key: 'name',
    dir: 'ascending',
  });
  const rows = [...users].sort((a, b) => {
    const r = sort.key === 'name' ? a.name.localeCompare(b.name) : a.signatures - b.signatures;
    return sort.dir === 'descending' ? -r : r;
  });
  const toggle = (key: 'name' | 'signatures') =>
    setSort((s) => ({
      key,
      dir: s.key === key && s.dir === 'ascending' ? 'descending' : 'ascending',
    }));
  return (
    <Table aria-label="Users sorted">
      <TableHeader>
        <TableRow>
          <TableHead
            sortDirection={sort.key === 'name' ? sort.dir : 'none'}
            onSort={() => toggle('name')}
          >
            Name
          </TableHead>
          <TableHead>Department</TableHead>
          <TableHead
            align="end"
            sortDirection={sort.key === 'signatures' ? sort.dir : 'none'}
            onSort={() => toggle('signatures')}
          >
            Signatures
          </TableHead>
        </TableRow>
      </TableHeader>
      <TableBody>
        {rows.map((u) => (
          <TableRow key={u.email}>
            <TableCell>{u.name}</TableCell>
            <TableCell>{u.department}</TableCell>
            <TableCell numeric>{u.signatures}</TableCell>
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
}

