virtualized-list.Listbox:
import * as React from 'react';
import { VirtualizedList } from '@bindshq/stance-react';

const people = [
  'Priya Nair',
  'Amara Okafor',
  'Lukas Brenner',
  'Hana Sato',
  'Tomás Ruiz',
  'Owen Price',
  'Zainab Haddad',
  'Mateja Kovač',
];

const recipients = Array.from({ length: 2000 }, (_, i) => ({
  id: `r${i}`,
  name: `${people[i % 8]} (${i + 1})`,
}));

export function Listbox() {
  const [selected, setSelected] = React.useState<React.Key | null>(null);
  return (
    <div style={{ display: 'grid', gap: 8 }}>
      <VirtualizedList
        role="listbox"
        aria-label="Choose a recipient"
        items={recipients}
        itemHeight={40}
        height={240}
        getItemKey={(r) => r.id}
        selectedKey={selected}
        onSelectionChange={setSelected}
        renderItem={(r) => r.name}
      />
      <p style={{ margin: 0 }}>
        Selected: {selected ? recipients.find((r) => r.id === selected)?.name : 'none'}
      </p>
    </div>
  );
}

