      items={notes}
      height={300}
      estimatedItemHeight={64}
      getItemKey={(n) => n.id}
      renderItem={(n) => (
        <div style={{ display: 'flex', gap: 12, padding: '12px 0', alignItems: 'flex-start' }}>
